insert into public.admin_help_items(help_key,title_fa,body_fa,title_en,body_en,warning_fa,warning_en) values
('seo.auto','سئوی خودکار','این ابزار بر اساس عنوان و محتوای همان صفحه، عنوان و توضیح مناسب برای موتور جستجو پیشنهاد می‌دهد و ذخیره می‌کند. می‌توانید بعداً متن را دستی ویرایش کنید.','Automatic SEO','This tool creates and saves a search title and description from the page title and content. You can edit the result manually at any time.','تولید خودکار جای بررسی انسانی را برای صفحات مهم نمی‌گیرد.','Automatic generation does not replace human review for important pages.'),
('analytics.views','بازدید صفحه','هر بار که یک صفحه عمومی سایت باز می‌شود یک Page View ثبت می‌شود. بازدید پنل مدیریت در این عدد حساب نمی‌شود.','Page views','A Page View is recorded whenever a public page is opened. Admin-panel views are excluded.',null,null),
('analytics.visitors','کاربر یکتا','یک شناسه ناشناس مرورگر برای برآورد تعداد کاربران یکتا استفاده می‌شود. اطلاعات هویتی یا IP خام برای این شاخص ذخیره نمی‌شود.','Unique visitors','An anonymous browser identifier is used to estimate unique visitors. Identifying information and raw IP addresses are not stored for this metric.',null,null),
('analytics.sessions','نشست بازدید','Session مجموعه بازدیدهای یک کاربر در یک نشست مرورگر است و برای درک تعداد دفعات مراجعه استفاده می‌شود.','Sessions','A session groups page activity within one browser session and helps estimate visit frequency.',null,null),
('analytics.conversions','تبدیل','Conversion یعنی عملیاتی که برای کسب‌وکار ارزش دارد؛ مثل ارسال فرم، درخواست همکاری یا کلیک روی اقدام اصلی.','Conversions','A conversion is a valuable business action such as submitting a form, requesting contact or completing a primary call to action.',null,null)
